// Convert response into JSON
let response = pm.response.json();

// Retrieve values
let token = response.token;
let userId = response.userId;

// Store in collection Variables
pm.collectionVariables.set("token", token);
pm.collectionVariables.set("userId", userId);

// Print in Postman Console
console.log("Token : " + token);
console.log("User ID : " + userId);

pm.test("Status code validation",()=>{
    pm.response.to.have.status(200);
    pm.expect(response).to.have.property("token")
    pm.expect(response.token).to.not.be.null;
    pm.expect(response.message).to.not.be.null;
    pm.expect(response.userId).to.not.be.null;
    pm.expect(response.token).to.be.a('string');
    pm.expect(response.message).to.equal("Login Successfully");
});

pm.test("Token and userId validation", () => {

    pm.expect(response.token).to.eql(pm.collectionVariables.get("token"));    
    pm.expect(response.userId).to.eql(pm.collectionVariables.get("userId"));    
});

